    aggregator POM, because the orchestrator copies this directory into isolated workspaces.
  -->
  <parent>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-parent</artifactId>
    <version>4.1.2</version>
    <relativePath/>
  </parent>

  <groupId>io.github.marishasahay.agentic</groupId>
  <artifactId>url-shortener</artifactId>
  <version>0.1.0-SNAPSHOT</version>
  <name>URL Shortener</name>
  <description>URL shortener service built and evolved by the agentic SDLC orchestrator.</description>

  <properties>
    <java.version>21</java.version>
    <jacoco.version>0.8.16</jacoco.version>
    <checkstyle-plugin.version>3.6.0</checkstyle-plugin.version>
    <checkstyle.version>14.3.0</checkstyle.version>
    <springdoc.version>3.1.1</springdoc.version>
